<script setup>
import { ref,watch,onBeforeUnmount,computed } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { get } from '../services/api'
import { date,money,statusLabels,activityTitle } from '../entities'
import LoadState from '../components/LoadState.vue'
const route=useRoute(),router=useRouter(),data=ref(null),busy=ref(false),error=ref(null)
let controller,version=0
const titles={clients:'Clients',merchants:'Professionnels',shops:'Boutiques',vehicles_active:'Véhicules actifs',vehicles_sold:'Véhicules vendus',rentals_active:'Locations actives',reservations_pending:'Réservations en attente',transactions_demo:'Transactions DEMO · période'}
const seriesLabels={registrations:'Inscriptions',listings:'Annonces créées',reservations:'Réservations',sales:'Ventes livrées'}
const max=computed(()=>Math.max(1,...Object.values(data.value?.series||{}).flat().map(x=>x.count)))
function points(rows){return rows.map((r,i)=>`${24+i*492/Math.max(1,rows.length-1)},${154-r.count/max.value*130}`).join(' ')}
function update(key,value){router.push({query:{...route.query,[key]:value}})}
async function load(){const v=++version;controller?.abort();controller=new AbortController();busy.value=true;error.value=null;data.value=null;try{const r=await get('/admin'+route.path,route.query,controller.signal);if(v===version)data.value=r.data}catch(e){if(v===version&&!controller.signal.aborted)error.value=e}finally{if(v===version)busy.value=false}}
watch(()=>route.fullPath,load,{immediate:true});onBeforeUnmount(()=>{version++;controller?.abort()})
</script>
<template><div><div class="page-title"><div><span class="eyebrow">BolideMarket · Administration</span><h1>{{ route.path==='/reports'?'Rapports':'Vue d’ensemble' }}</h1></div><div class="actions"><label>Période UTC<select :value="route.query.period||30" @change="update('period',$event.target.value)"><option value="7">7 jours</option><option value="30">30 jours</option><option value="90">90 jours</option><option value="365">Année glissante</option></select></label><label>Périmètre<select :value="route.query.scope||data?.scope||'demo'" @change="update('scope',$event.target.value)"><option value="demo">Démonstration</option><option value="real">Données réelles</option><option value="all">Tous · supervision</option></select></label></div></div><LoadState :busy="busy" :error="error" @retry="load"><template v-if="data"><p class="lead">{{ data.scope==='demo'?'Données de démonstration':data.scope==='real'?'Données réelles — DEMO exclue':'Toutes les données — supervision' }} · {{ date(data.as_of) }}</p><div class="kpis"><article v-for="(value,key) in data.kpis" :key="key"><span>{{ titles[key] }}</span><strong>{{ value.toLocaleString('fr-FR') }}</strong><small>{{ key==='transactions_demo'?'DEMO uniquement':'Instantané actuel' }}</small></article></div><div class="dashboard-grid"><section class="panel chart-panel"><div class="section-title"><h2>Évolution de l’activité</h2><span class="badge">{{ data.period }} jours</span></div><div class="legend"><span v-for="(title,key,index) in seriesLabels" :key="key" :class="'series-'+index">{{ title }}</span></div><svg viewBox="0 0 540 180" role="img" aria-label="Évolution des inscriptions, annonces, réservations et ventes"><path d="M24 24V154H516" fill="none" stroke="#ddd"/><text x="2" y="26">{{ max }}</text><text x="8" y="158">0</text><polyline v-for="(rows,key,index) in data.series" :key="key" :points="points(rows)" fill="none" :class="'line-'+index" stroke-width="2.5"/></svg><div class="chart-range"><span>{{ data.series.registrations[0]?.date }}</span><span>{{ data.series.registrations.at(-1)?.date }}</span></div><details><summary>Consulter les chiffres du graphique</summary><div class="table-wrap"><table><thead><tr><th>Date UTC</th><th v-for="title in seriesLabels" :key="title">{{ title }}</th></tr></thead><tbody><tr v-for="(row,i) in data.series.registrations" :key="row.date"><td>{{ row.date }}</td><td v-for="(rows,key) in data.series" :key="key">{{ rows[i]?.count||0 }}</td></tr></tbody></table></div></details></section><section class="panel"><h2>Répartition du parc</h2><strong class="fleet-total">{{ data.fleet.total }} <small>véhicules</small></strong><div v-for="key in ['available','rented','sold','other']" :key="key" class="fleet-row"><span>{{ statusLabels[key] }}</span><strong>{{ data.fleet[key] }}</strong><meter :value="data.fleet[key]" :max="Math.max(1,data.fleet.total)" :aria-label="statusLabels[key]"/></div></section></div><div class="dashboard-grid"><section class="panel"><h2>Répartition géographique</h2><p v-if="!data.geography.length" class="muted">Aucune annonce dans ce périmètre.</p><div v-else class="table-wrap"><table><thead><tr><th>Pays</th><th>Ville</th><th>Annonces</th></tr></thead><tbody><tr v-for="(place,index) in data.geography" :key="index"><td>{{ place.country }} · {{ place.country_code }}</td><td>{{ place.city }}</td><td>{{ place.count }}</td></tr></tbody></table></div></section><section class="panel"><h2>Encaissements DEMO</h2><p class="muted">Période sélectionnée · Aucune conversion</p><p v-if="!data.payments_demo.length">Aucun paiement simulé sur cette période.</p><article v-for="payment in data.payments_demo" :key="payment.currency" class="revenue"><span class="badge">DEMO · {{ payment.currency }}</span><strong>{{ money(payment.amount_minor,payment.currency,payment.minor_unit) }}</strong><small>{{ payment.count }} paiements simulés</small></article></section></div><section class="panel"><div class="section-title"><h2>Activité administrative récente</h2><RouterLink to="/activity">Voir le journal →</RouterLink></div><p v-if="!data.activity.length" class="muted">Les prochaines décisions de modération apparaîtront ici.</p><ul v-else class="related"><li v-for="entry in data.activity" :key="entry.id"><RouterLink :to="'/'+entry.subject_type+'/'+entry.subject_id">{{ activityTitle(entry.action) }}</RouterLink><span>{{ entry.reason }}</span><span>{{ entry.admin.name }} · {{ date(entry.created_at) }}</span></li></ul></section><p class="help">{{ data.demo_notice }}</p></template></LoadState></div></template>
